struct C
{
    static void Main()
    {
        long x;
        string y;

        var c = new C();
        (x, y) = c;
        System.Console.WriteLine(x + " " + y);
    }
}
static class D
{
    public static void Deconstruct(this ref C value, out int a, out string b)
    {
        a = 1;
        b = "hello";
    }
}

